#include "HashSetClosed.h"
namespace {bool prime(int n){if(n<2)return false;for(int i=2;i<=n/i;++i)if(n%i==0)return false;return true;}int nextPrime(int n){if(n<2)n=2;while(!prime(n))++n;return n;}}
HashSetClosed::HashSetClosed(int c):slots_(nextPrime(c)){}
int HashSetClosed::hash(int v)const{int i=v%capacity();return i<0?i+capacity():i;}
bool HashSetClosed::insertRaw(int v){int h=hash(v);for(int k=0;k<capacity();++k){int i=(h+k)%capacity();if(slots_[i].state!=SlotState::Occupied){slots_[i]={v,SlotState::Occupied};++size_;return true;}}return false;}
void HashSetClosed::rehash(int c){auto old=slots_;slots_.assign(nextPrime(c),{});size_=0;for(auto s:old)if(s.state==SlotState::Occupied)insertRaw(s.value);}
bool HashSetClosed::contains(int v,std::vector<Event>* e)const{int h=hash(v);if(e)e->push_back({"Hash: "+std::to_string(v)+" % "+std::to_string(capacity())+" = "+std::to_string(h),h});for(int k=0;k<capacity();++k){int i=(h+k)%capacity();if(e)e->push_back({"Inspect slot "+std::to_string(i),i});if(slots_[i].state==SlotState::Empty)return false;if(slots_[i].state==SlotState::Occupied&&slots_[i].value==v)return true;}return false;}
bool HashSetClosed::add(int v,std::vector<Event>* e){if(contains(v))return false;if((double)(size_+1)/capacity()>.5){int old=capacity();rehash(old*2+1);if(e)e->push_back({"Rehashed table from "+std::to_string(old)+" to "+std::to_string(capacity()),-1});}int h=hash(v);if(e)e->push_back({"Hash: "+std::to_string(v)+" % "+std::to_string(capacity())+" = "+std::to_string(h),h});for(int k=0;k<capacity();++k){int i=(h+k)%capacity();if(e)e->push_back({"Inspect slot "+std::to_string(i),i});if(slots_[i].state==SlotState::Occupied){if(e)e->push_back({"Collision; probe next slot",i,true});continue;}slots_[i]={v,SlotState::Occupied};++size_;if(e)e->push_back({"Inserted "+std::to_string(v)+" at slot "+std::to_string(i),i});return true;}return false;}
bool HashSetClosed::remove(int v,std::vector<Event>* e){int h=hash(v);for(int k=0;k<capacity();++k){int i=(h+k)%capacity();if(e)e->push_back({"Inspect slot "+std::to_string(i),i});if(slots_[i].state==SlotState::Empty)return false;if(slots_[i].state==SlotState::Occupied&&slots_[i].value==v){slots_[i].state=SlotState::Deleted;--size_;if(e)e->push_back({"Removed value; slot marked DELETED",i});return true;}}return false;}
